mapper.select:
select
    (select count(*) from Gantt_Tasks_Process gtp where gtp.task_id=mn.task_id and gtp.Gtp_State!=3) as tasksProcess,
    mn.*
from Gantt_Tasks mn
left join Gantt_Plan gp on mn.plan_id=gp.plan_id

    
        and mn.task_Importance=#{params.taskImportance}
    
    
        and mn.task_Type=#{params.taskType}
    
    
        and mn.task_Parent=#{params.taskParent}
    
    
        and gp.p_id=#{params.pId}
    

order by mn.Task_Sort asc

select
(select COUNT(*) from Gantt_Tasks_Process gtp where gtp.task_id=mn.task_id and gtp.Gtp_State!=3) as
tasksProcess,
gs.Gs_Section as gsSection,
mn.*
from Gantt_Tasks mn
left join Gant_Section gs on gs.id=mn.gs_id
left join Gantt_Plan gp on mn.plan_id=gp.plan_id

    gp.Plan_State = 7
    
        and gp.p_id=#{params.pId}
    
    
        and gp.plan_Id=#{params.planId}
    
    
    
        and mn.Task_Text in
        
            #{value}
        
    
    
        
            
                
                    gs.Gs_Section IS NULL
                
                
                    gs.Gs_Section = #{gsSection}
                
            
        
    
    
        and mn.Task_Type in
        
            #{value}
        
    
    
        and 1 = 0
    
    
        
            mn.Task_Importance = #{taskImportance}

select distinct ${value}
from Gantt_Tasks mn
left join Gant_Section gs on gs.id=mn.gs_id
left join Gantt_Plan gp on mn.plan_id=gp.plan_id

    gp.Plan_State = 7
    
        and gp.p_id=#{params.pId}
    
    
    
        and mn.Task_Text in
        
            #{value}
        
    
    
    
        and mn.Task_Type in
        
            #{value}

mapper.update:
update gantt_tasks
set Task_Progress=100,
    Task_Finish_Time=#{stateTime},
    Task_State=7
where plan_id = #{planId}
  and Cpl_Id = #{cplId}

mapper.select:
select count(1) from Gantt_Tasks gt left join Gantt_Plan gp on gt.Plan_Id=gp.Plan_Id where
gt.Task_Progress=#{progress} and gp.Plan_State=7

    and gp.Te_Id = #{teId}

select gs.gs_section as gsSection, gs.gs_describe as gsDescribe, (case when (select count(*) from Gantt_Tasks_Process p where p.Task_Id=mn.Task_Id)>0 then true else false end) as taskFilling, (select ft.T_Name from SYS_FileTemplate ft where ft.T_Code=mn.Task_Start_T_Code limit 1) as taskStartTName, (select ft.T_Name from SYS_FileTemplate ft where ft.T_Code=mn.Task_End_T_Code limit 1) as taskEndTName, mn.* from Gantt_Tasks mn left join gant_section gs on gs.id=mn.gs_id where mn.Plan_Id in
#{planId}
order by Task_Sort asc

select con.Con_Name as conName, pro.P_Name as pName, pro.P_Name_History as pNameHistory, prod.D_Name as pCompetentDepartmentName, dep.D_Name as dName, gp.Plan_Name as planName, gp.P_Id as pId, u.U_MTel as uMtel, u.U_Tel as uTel, u.U_Email as uEmail, c1.C_Name_History as pConstructionUnitNameHistory, c2.C_Name_History as uCNameHistory, c1.C_Name as pConstructionUnitName, c2.C_Name as uCName, c1.C_Abbreviation as pConsAbbName, c2.C_Abbreviation as uCAbbName, gs.gs_section as gsSection, gs.gs_describe as gsDescribe, mn.* from Gantt_Tasks mn left join Gantt_Plan gp on mn.Plan_Id=gp.Plan_Id left join Con_Contract con on con.Con_Id=gp.Con_Id left join Pre_Project pro on pro.P_Id=gp.P_Id left join SYS_Department prod on prod.D_Id=pro.P_Competent_Department left join SYS_Department dep on dep.D_ID=gp.Plan_D_Id left join SYS_Company c1 on pro.P_Construction_Unit=c1.C_Id left join Sys_User u on u.U_Id=mn.Task_Uid left join SYS_Company c2 on u.C_ID=c2.C_Id left join gant_section gs on gs.id=mn.gs_id where gp.Plan_State=7 and mn.Task_State=1 and mn.Task_Parent=#{params.taskId}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Task_Start_Date ASC
limit #{params.start},#{params.size}

select con.Con_Name as conName, pro.P_Name as pName, dep.D_Name as dName, prod.D_Name as pCompetentDepartmentName, c1.C_Name as pConstructionUnitName, gp.Plan_Name as planName, gp.P_Id as pId, u.U_MTel as uMtel, u.U_Tel as uTel, u.U_Email as uEmail, c2.C_Name_History as uCNameHistory, c2.C_Name as uCName, c1.C_Abbreviation as pConsAbbName, c2.C_Abbreviation as uCAbbName, gs.gs_section as gsSection, gs.gs_describe as gsDescribe, mn.* from Gantt_Tasks mn left join Gantt_Plan gp on mn.Plan_Id = gp.Plan_Id left join Con_Contract con on con.Con_Id = gp.Con_Id left join Pre_Project pro on pro.P_Id = gp.P_Id left join SYS_Department prod on prod.D_Id = pro.P_Competent_Department left join SYS_Department dep on dep.D_ID = gp.Plan_D_Id left join SYS_Company c1 on pro.P_Construction_Unit = c1.C_Id left join Sys_User u on u.U_Id = mn.Task_Uid left join SYS_Company c2 on u.C_ID = c2.C_Id left join gant_section gs on gs.id=mn.gs_id where gp.Plan_State = 7 and mn.Task_State = 1 and mn.Task_Parent = '0' and gp.P_Id = #{pId}
and gp.Plan_Type in
#{type}
order by mn.Task_Start_Date,mn.Task_Sort asc

select gt.*
from Gantt_Tasks gt
left join Gantt_Plan mn on gt.Plan_Id=mn.Plan_Id
${authSql} and mn.Plan_State=7 and gt.Task_State=1

    and mn.P_Id=#{params.pId}


    and mn.Plan_Type in
    
        #{type}
    


        and mn.plan_Type= #{params.planType}


    and (mn.Plan_Type not in
    
        #{exType}
    
    or mn.Plan_Type is null)


    and mn.plan_Start >= #{params.planStartDateStart}


    and mn.plan_Start <= #{params.planStartDateEnd}


    and mn.plan_End >= #{params.planEndDateStart}


    and mn.plan_End <= #{params.planEndDateEnd}

select
con.Con_Name as conName, dep.D_Name as dName, mn.Plan_Name as planName, mn.P_Id as pId, u.U_MTel as uMtel, u.U_Tel as uTel, u.U_Email as uEmail, c2.C_Name_History as uCNameHistory, c2.C_Name as uCName, c2.C_Abbreviation as uCAbbName, gs.gs_section as gsSection, gs.gs_describe as gsDescribe, gt.* from Gantt_Tasks gt left join gant_section gs on gs.id=gt.gs_id left join Gantt_Plan mn on gt.Plan_Id=mn.Plan_Id left join Con_Contract con on con.Con_Id=mn.Con_Id
left join SYS_Department dep on dep.D_ID=mn.Plan_D_Id left join Sys_User u on u.U_Id=gt.Task_Uid left join SYS_Company c2 on u.C_ID=c2.C_Id ${params.authSql} and gt.Task_Finish_Time is not null
and mn.plan_type=#{params.planType}
and pro.P_Id=#{params.pId}
and likePname(#{params.pName},pro.P_Id)=true
and pro.P_Name like concat('%',#{params.pName},'%')
and gt.Task_Text like concat('%',#{params.taskText},'%')
and mn.Plan_Name like concat('%',#{params.planName},'%')
and mn.Plan_Type in
#{planType}
and mn.Plan_State=#{params.planState}
order by gt.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by gt.Task_Finish_Time DESC

mapper.sql:
and mn.Plan_State=7
and gt.Task_State=1 and

    (
    gt.Task_End_Date+1,gt.Task_Finish_Time)>0
    or(
    gt.Task_End_Date+1,now())>=0 and gt.Task_Finish_time is null
    )
    or (gt.Task_Finish_Time is null andnow(),gt.Task_End_Date+1)>0 and
    now(),gt.Task_End_Date+1)<30)
    )


    (gt.Task_Finish_Time is null andnow(),gt.Task_End_Date+1)>0 and
    now(),gt.Task_End_Date+1)<30)


    (
    gt.Task_End_Date+1,gt.Task_Finish_Time)>0
    or(
    gt.Task_End_Date+1,now())>=0 and gt.Task_Finish_time is null
    )
    )


    and mn.P_Id=#{params.pId}


    and dep.D_Id=#{params.dId}


    and mn.Plan_Type = #{params.planType}


    and mn.Plan_Type in
    
        #{type}
    


    and con.Con_Name like concat('%',#{params.conName},'%')


    
        
            and likePname(#{params.pName},pro.P_Id)=true
        
        
            and pro.P_Name like concat('%',#{params.pName},'%')
        
    


    and gt.Task_Text like concat('%',#{params.taskText},'%')


    and gt.task_Start_Date > #{params.taskStartDateStart}


    and gt.task_Start_Date < #{params.taskStartDateEnd}


    and gt.task_End_Date > #{params.taskEndDateStart}


    and gt.task_End_Date < #{params.taskEndDateEnd}


    
        and gt.Task_Progress=100
    
    
        and gt.Task_Progress!=100
    


    
        AND gt.Task_End_Date < NOW()
    
    
        AND gt.Task_End_Date >= NOW()
    


    and (mn.Plan_Type not in
    
        #{exType}
    
    or mn.Plan_Type is null)

mapper.select:
select con.Con_Name as conName, pro.P_Name as pName, pro.P_Name_History as pNameHistory, dep.D_Name as dName, prod.D_Name as pCompetentDepartmentName, c1.C_Name_History as pConstructionUnitNameHistory, c1.C_Name as pConstructionUnitName, c1.C_Abbreviation as pConsAbbName, mn.Plan_Name as planName, mn.P_Id as pId, gs.gs_section as gsSection, gs.gs_describe as gsDescribe, gt.* from Gantt_Tasks gt left join gant_section gs on gs.id=gt.gs_id left join Gantt_Plan mn on gt.Plan_Id=mn.Plan_Id left join Con_Contract con on con.Con_Id=mn.Con_Id left join Pre_Project pro on pro.P_Id=mn.P_Id left join SYS_Department prod on prod.D_Id=pro.P_Competent_Department left join SYS_Department dep on dep.D_ID=mn.Plan_D_Id left join SYS_Company c1 on pro.P_Construction_Unit=c1.C_Id ${params.authSql}
order by gt.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by gt.Task_End_Date DESC
limit #{params.start},#{params.size}

select pro.P_Name as pName, proc.C_Name as pConsName, proc.C_Abbreviation as pConsAbbName, sd.D_Name as dName, gs.gs_section as gsSection, gs.gs_describe as gsDescribe, gt.* from Gantt_Tasks gt left join gant_section gs on gs.id=gt.gs_id left join Gantt_Plan gp on gt.Plan_Id=gp.Plan_Id left join Pre_Project pro on pro.P_Id=gp.P_Id left join SYS_Company proc on proc.C_Id=pro.P_Construction_Unit left join Sys_Department sd on sd.D_Id=pro.P_Competent_Department where 1=1
and gp.Plan_Type = #{params.planType}
and gp.Plan_Name like concat('%',#{params.planName},'%')
and gp.Plan_Id in
#{planId}
and gp.P_Id in
#{pId}
order by gp.P_Id asc
